import {LANGUAGES,SOUND_FIELDS,prompts,soundPlan} from './engine.mjs';
import {BUILTIN_LIBRARY,LIBRARY_FIELDS,libraryEntries,validateLibrary,applySuggestion} from './library.mjs';
export function mountExtensions(api){
 const {node,button,$,t,commit,persist,download,copy,status}=api,get=api.getState,KEYLIB='artoftomworks.scene-dna.library.v1';let custom={schema:'artoftomworks.scene-dna.library',version:1,entries:[]},settings={model:'',cpu:true},busy=null,models=[];const widgets=new Map();
 try{custom=validateLibrary(JSON.parse(localStorage.getItem(KEYLIB)));}catch{}try{const s=JSON.parse(localStorage.getItem('artoftomworks.scene-dna.translator'));if(typeof s?.model==='string')settings.model=s.model;settings.cpu=s?.cpu!==false;}catch{}
 const named=e=>get().language==='HU'?e.hu||e.name:e.name,fieldCaption=k=>LIBRARY_FIELDS.indexOf(k)<8?api.fieldName(k==='timeText'?'time':k):k==='artist'?t('author'):t(k==='profile'?'profile':k);
 function storeLibrary(){try{localStorage.setItem(KEYLIB,JSON.stringify(custom));}catch{status('libraryError');}}
 function storeSettings(){try{localStorage.setItem('artoftomworks.scene-dna.translator',JSON.stringify(settings));}catch{}}
 function suggestion(parent,input,field,after){const wrap=node('div');wrap.className='suggestion';const select=node('select');select.setAttribute('aria-label',t('suggestions')+' · '+fieldCaption(field));select.append(new Option(t('choose'),''));const entries=libraryEntries(custom,field);const groups=new Map();const groupNames=get().language==='HU'?{setup:'Portréfény / fényrendszer',source:'Fényforrás',direction:'Fényirány / derítés',colour:'Színes fény',effect:'Optikai hatás',custom:'Saját ajánlások',artist:'Alkotói referenciák'}:{setup:'Portrait / lighting setup',source:'Light source',direction:'Light direction / fill',colour:'Coloured light',effect:'Optical effect',custom:'Own suggestions',artist:'Artist references'};for(const entry of entries){const option=node('option',named(entry)+(entry.field==='artist'?' · '+t('author'):''));option.value=entry.id;option.title=entry.text;let group=groups.get(entry.group);if(!group){group=node('optgroup');group.label=groupNames[entry.group]||t('suggestions');groups.set(entry.group,group);select.append(group);}group.append(option);}
  const explanation=node('p');explanation.className='muted suggestion-description';const mode=node('select');mode.setAttribute('aria-label',t('insert'));mode.append(new Option(t('append'),'append'),new Option(t('replace'),'replace'));const include=node('input');include.type='checkbox';const includeLabel=node('label');includeLabel.className='lock';includeLabel.append(include,node('span',t('includeAuthor')));includeLabel.hidden=true;
  const insert=button(t('insert'),()=>{const entry=entries.find(e=>e.id===select.value);if(!entry)return;try{input.value=applySuggestion(input.value,entry,mode.value,include.checked);after(input.value);explanation.textContent=entry.text;}catch{status('tooLong');}});insert.disabled=true;select.onchange=()=>{const e=entries.find(e=>e.id===select.value);insert.disabled=!e;explanation.textContent=e?.text||'';includeLabel.hidden=!e?.author;};const manage=button('+ '+t('manage'),()=>openLibrary(field,input.value));const row=node('div');row.className='toolbar';row.append(select,mode,insert,manage);wrap.append(row,includeLabel,explanation);parent.append(wrap);}
 // Full library editor; edits affect a preset, not already inserted project text.
 const dialog=node('dialog');dialog.id='libraryDialog';const heading=node('h2'),help=node('p'),list=node('select'),category=node('select'),name=node('input'),desc=node('textarea'),author=node('input'),msg=node('p');name.maxLength=author.maxLength=180;desc.maxLength=2000;desc.rows=5;list.id='libraryEntry';category.id='libraryCategory';name.id='libraryName';desc.id='libraryText';author.id='libraryAuthor';let editing='';
 const inputs=[];for(const [key,input]of [['suggestions',list],['recipe',category],['entryName',name],['description',desc],['author',author]]){const label=node('label'),caption=node('span');label.append(caption,input);inputs.push([caption,key]);dialog.append(label);}const actions=node('div');actions.className='toolbar';const fresh=button('',()=>{editing='';list.value='';name.value=desc.value=author.value='';del.disabled=true;});const save=button('',()=>{try{const id=editing||'custom-'+crypto.randomUUID();const entry={id,field:category.value,name:name.value,text:desc.value,author:author.value};custom=validateLibrary({...custom,entries:[...custom.entries.filter(e=>e.id!==id),entry]});editing=id;storeLibrary();msg.textContent=t('entrySaved');editorLabels();api.render();}catch{msg.textContent=t('libraryError');}});const del=button('',()=>{if(!editing)return;custom.entries=custom.entries.filter(e=>e.id!==editing);editing='';name.value=desc.value=author.value='';storeLibrary();editorLabels();msg.textContent=t('entryRemoved');api.render();});const exportLib=button('',()=>download(JSON.stringify(custom,null,2),'SceneDNA_Library.json','application/json'));const libPicker=node('input');libPicker.id='libraryPicker';libPicker.type='file';libPicker.accept='.json';libPicker.hidden=true;const importLib=button('',()=>{libPicker.value='';libPicker.click();});const close=button('',()=>dialog.close());for(const [b,id]of [[fresh,'libraryNew'],[save,'librarySave'],[del,'libraryDelete'],[exportLib,'libraryExport'],[importLib,'libraryImport'],[close,'libraryClose']])b.id=id;actions.append(fresh,save,del,exportLib,importLib,close);dialog.prepend(heading,help);dialog.append(actions,msg,libPicker);document.body.append(dialog);
 function editorLabels(){heading.textContent=t('library');help.textContent=t('libraryHelp');help.className='muted';for(const [span,key]of inputs)span.textContent=t(key);const selected=category.value;category.replaceChildren();for(const f of LIBRARY_FIELDS)category.append(new Option(fieldCaption(f),f));category.value=LIBRARY_FIELDS.includes(selected)?selected:'lighting';list.replaceChildren(new Option(t('newEntry'),''));for(const e of custom.entries)list.append(new Option(e.name,e.id));list.value=editing;del.disabled=!editing;for(const [b,k]of [[fresh,'newEntry'],[save,'saveEntry'],[del,'deleteEntry'],[exportLib,'exportLib'],[importLib,'importLib'],[close,'close']])b.textContent=t(k);}
 list.onchange=()=>{editing=list.value;const e=custom.entries.find(e=>e.id===editing);name.value=e?.name||'';desc.value=e?.text||'';author.value=e?.author||'';if(e)category.value=e.field;del.disabled=!e;};
 libPicker.onchange=async()=>{try{const f=libPicker.files[0];if(!f)return;if(f.size>600000)throw Error();const data=validateLibrary(JSON.parse(await f.text())),merged=new Map(custom.entries.map(e=>[e.id,e]));for(const e of data.entries)merged.set(e.id,e);custom=validateLibrary({...data,entries:[...merged.values()]});storeLibrary();editing='';editorLabels();msg.textContent=t('allLoaded');api.render();}catch{msg.textContent=t('libraryError');}};
 function openLibrary(field='lighting',value=''){editing='';name.value=author.value='';desc.value=value;editorLabels();category.value=field;msg.textContent='';dialog.showModal();}
 $('libraryOpen').onclick=()=>openLibrary();
 function soundEditor(parent,sound,after,shared=false){for(const key of SOUND_FIELDS){const label=node('label');label.append(node('span',t(key)));const input=node('textarea');input.rows=2;input.maxLength=2000;input.value=sound[key]||'';if(!shared)input.placeholder=get().audio?.[key]||t('inherit');input.oninput=()=>{sound[key]=input.value;after();};label.append(input);parent.append(label);suggestion(parent,input,key,v=>{sound[key]=v;after();});}}
 function soundPanel(){const host=$('soundForm');host.replaceChildren();const label=node('label');label.append(node('span',t('audio')));const mode=node('select');for(const [v,key]of [['off','modeOff'],['prompt','modePrompt'],['post','modePost']])mode.append(new Option(t(key),v));mode.value=get().audio.mode;mode.onchange=()=>{get().audio.mode=mode.value;commit();};label.append(mode);host.append(label);soundEditor(host,get().audio,commit,true);}
 function shotSound(parent,shot){const details=node('details');details.append(node('summary',t('soundPerShot')));const fields=node('div');shot.sound??={};soundEditor(fields,shot.sound,commit);details.append(fields);parent.append(details);}
 function profiles(){const host=$('profileForm');host.replaceChildren();const label=node('label');label.append(node('span',t('profile')));const select=node('select');for(const [value,key]of [['generic','generic'],['ltx','ltx'],['h3','h3'],['custom','customProfile']])select.append(new Option(t(key),value));select.value=get().profile;select.onchange=()=>{get().profile=select.value;commit();profiles();};label.append(select);host.append(label,node('p',t('profileHint')));if(get().profile==='custom'){const l=node('label');l.append(node('span',t('profileNote')));const area=node('textarea');area.value=get().profileNote;area.rows=3;area.maxLength=2000;area.oninput=()=>{get().profileNote=area.value;commit();};l.append(area);host.append(l);suggestion(host,area,'profile',v=>{get().profileNote=v;commit();});}}
 const translator=$('translatorForm'),model=node('select'),refresh=button('',loadModels),cpu=node('input'),modelStatus=node('p');cpu.type='checkbox';model.id='translationModel';cpu.id='translationCPU';cpu.checked=settings.cpu;model.onchange=()=>{settings.model=model.value;storeSettings();};cpu.onchange=()=>{settings.cpu=cpu.checked;storeSettings();};
 async function loadModels(){if(location.protocol==='file:'){modelStatus.textContent=t('localNeeded');return;}refresh.disabled=true;try{const res=await fetch('/api/models');const data=await res.json();if(!res.ok)throw Error(data.error);models=data.models;model.replaceChildren(new Option(t('choose'),''));for(const name of models)model.append(new Option(name,name));if(!models.includes(settings.model))settings.model=models.find(n=>/promptstudio|qwen|gemma/i.test(n))||models[0]||'';model.value=settings.model;storeSettings();modelStatus.textContent=models.length?models.length+' · Ollama':t('localNeeded');}catch(e){modelStatus.textContent=t('localNeeded')+' '+e.message;}finally{refresh.disabled=false;}}
 function translationSettings(){translator.replaceChildren();const label=node('label');label.append(node('span',t('localModel')),model);const cpuLabel=node('label');cpuLabel.className='lock';cpuLabel.append(cpu,node('span',t('cpu')));refresh.textContent=t('refreshModels');translator.append(label,refresh,cpuLabel,node('p',t('modelHint')),node('p',t('bridgeHint')),modelStatus);if(!model.options.length)model.append(new Option(t('choose'),''));}
 function visible(shot,kind){const source=prompts(get(),shot)[kind],lang=shot.promptLanguages?.[kind]||'EN',cached=shot.translations?.[kind]?.[lang];return lang==='SOURCE'?{text:source,ready:true,lang,source}:{text:cached?.text||source,ready:!!cached&&cached.source===source,stale:!!cached&&cached.source!==source,lang,source};}
 function promptBlock(parent,shot,kind){const block=node('div');block.className='prompt-block';const bar=node('div');bar.className='toolbar prompt-toolbar';const title=node('strong',t(kind+'Prompt')),language=node('select');language.setAttribute('aria-label',t(kind+'Prompt')+' · '+t('language'));language.append(new Option(t('source'),'SOURCE'));const languageNames={EN:'English',HU:'Magyar',DE:'Deutsch',FR:'Français',ES:'Español',IT:'Italiano',PT:'Português',PL:'Polski'};for(const lang of LANGUAGES)language.append(new Option(languageNames[lang],lang));language.dataset.promptLanguage=kind;language.value=shot.promptLanguages?.[kind]||'EN';language.onchange=()=>{shot.promptLanguages??={image:'EN',video:'EN'};shot.promptLanguages[kind]=language.value;persist();showPrompt(shot,kind);};const area=node('textarea');area.readOnly=true;area.rows=8;area.dataset.prompt=kind;area.setAttribute('aria-label',t(kind+'Prompt'));const notice=node('p');notice.className='translation-notice';notice.setAttribute('role','status');const hint=node('p',t('translationHint'));hint.className='muted';const translate=button(t('translate'),()=>{if(busy){if(busy.shotId===shot.id&&busy.kind===kind)busy.controller.abort();return;}void requestTranslation(shot,kind);});translate.dataset.translate=kind;const copyButton=button(t('copy'),()=>{const v=visible(shot,kind);if(v.ready)void copy(v.text);else status('copyBlocked');});copyButton.dataset.copy=kind;copyButton.dataset.copyBelow=kind;copyButton.textContent=t('copy')+' · '+t(kind+'Prompt');copyButton.className='primary';const bottom=node('div');bottom.className='toolbar prompt-copy-bottom';bottom.append(copyButton);bar.append(title,language,translate);block.append(bar,notice,area,bottom,hint);parent.append(block);widgets.set(shot.id+kind,{language,area,notice,translate,copyButton});showPrompt(shot,kind);}
 function showPrompt(shot,kind){const w=widgets.get(shot.id+kind);if(!w)return;const v=visible(shot,kind);w.area.value=v.text;w.language.value=v.lang;w.copyButton.disabled=!v.ready;w.copyButton.title=v.ready?'':t('copyBlocked');const active=busy?.shotId===shot.id&&busy?.kind===kind;w.translate.textContent=t(active?'cancel':'translate');w.translate.disabled=v.lang==='SOURCE'||!!busy&&!active;w.notice.textContent=active?t('working'):v.stale?t('stale'):!v.ready?t('notReady'):v.lang==='SOURCE'?'':t('reviewTranslation');}
 function refreshPrompts(){for(const shot of get().shots)for(const kind of ['image','video'])showPrompt(shot,kind);}
 async function requestTranslation(shot,kind){const v=visible(shot,kind);if(v.lang==='SOURCE')return;if(location.protocol==='file:'||!settings.model){const w=widgets.get(shot.id+kind);if(w)w.notice.textContent=t('localNeeded');return;}const controller=new AbortController(),projectId=get().id,modelName=settings.model;busy={shotId:shot.id,kind,controller};refreshPrompts();try{const res=await fetch('/api/translate',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({text:v.source,language:v.lang,model:modelName,cpu:settings.cpu})});const data=await res.json();if(!res.ok)throw Error(data.error||t('translationError'));if(get().id!==projectId)return;const current=get().shots.find(s=>s.id===shot.id);if(!current)return;current.translations??={};current.translations[kind]??={};current.translations[kind][v.lang]={source:v.source,text:data.translation,model:modelName};persist();}catch(e){const w=widgets.get(shot.id+kind);if(w)w.error=e.name==='AbortError'?t('cancel'):t('translationError')+' '+e.message;}finally{busy=null;refreshPrompts();const w=widgets.get(shot.id+kind);if(w?.error){w.notice.textContent=w.error;delete w.error;}}}
 function exportSound(){let time=0;const text=get().shots.map((shot,i)=>{const start=time;time+=shot.duration;return `${i+1}. ${shot.title} · ${start.toFixed(1)}–${time.toFixed(1)}s\n${soundPlan(get(),shot)||'—'}`;}).join('\n\n');download('Scene DNA — '+t('audio')+'\n'+get().title+'\n\n'+text,'SceneDNA_SoundPlan.txt');}
 $('exportSound').onclick=exportSound;
 function render(){editorLabels();soundPanel();profiles();translationSettings();refreshPrompts();}
 return {suggestion,shotSound,promptBlock,showPrompt,visible,render,openLibrary,clearWidgets:()=>widgets.clear(),loadModels};
}
